247	/****************************************************************************
248	 * Name: esp_lcd_del_dsi_bus
249	 *
250	 * Description:
251	 *   Delete DSI bus — disable clocks and release resources.
252	 ****************************************************************************/
253	
254	int esp_lcd_del_dsi_bus(esp_lcd_dsi_bus_handle_t bus)
255	{
256	  int bus_id;
257	
258	  if (!bus)
259	    {
260	      return -EINVAL;
261	    }
262	
263	  bus_id = bus->bus_id;
264	
265	  /* Disable PHY clocks */
266	
267	  PERIPH_RCC_ATOMIC()
268	    {
269	      mipi_dsi_ll_enable_phy_pllref_clock(bus_id, false);
270	      mipi_dsi_ll_enable_phy_config_clock(bus_id, false);
271	    }
272	
273	  /* Disable APB bus clock */
274	
275	  PERIPH_RCC_ATOMIC()
276	    {
277	      mipi_dsi_ll_enable_bus_clock(bus_id, false);
278	    }
279	
280	  /* Clear static instance */
281	
282	  memset(bus, 0, sizeof(esp_lcd_dsi_bus_t));
283	
284	  syslog(LOG_INFO, "[DSI-BUS] Bus deleted\n");
285	  return 0;
286	}
