85	
86	int esp_dsi_fb_initialize(void)
87	{
88	  int ret;
89	
90	  syslog(LOG_INFO, "[DSI-FB] Starting initialization\n");
91	
92	  /* 1. PHY LDO (2.5V) */
93	
94	  dsi_phy_ldo_enable();
95	  syslog(LOG_INFO, "[DSI-FB] PHY LDO enabled\n");
96	
97	  /* 2. DSI Bus (PHY + Host) */
98	
99	  esp_lcd_dsi_bus_config_t bus_cfg;
100	  memset(&bus_cfg, 0, sizeof(bus_cfg));
101	  bus_cfg.bus_id = 0;
102	  bus_cfg.num_data_lanes = 2;
103	  bus_cfg.lane_bit_rate_mbps = 1000.0f;
104	  bus_cfg.phy_clk_src = 0; /* default XTAL */
105	  bus_cfg.flags.clock_lane_force_hs = false;
106	
107	  ret = esp_lcd_new_dsi_bus(&bus_cfg, &g_dsi_bus);
108	  if (ret != 0)
109	    {
110	      syslog(LOG_ERR, "[DSI-FB] Bus init failed: %d\n", ret);
111	      return ret;
112	    }
113	
114	  syslog(LOG_INFO, "[DSI-FB] Bus init OK\n");
115	
116	  /* 3. Panel reset + DCS commands (while in command mode) */
117	
118	  panel_reset();
119	  panel_send_dcs(&g_dsi_bus->hal);
120	  syslog(LOG_INFO, "[DSI-FB] Panel reset + Sleep Out done\n");
121	
122	  /* 4. DPI Panel (Bridge + DMA link) */
123	
124	  esp_lcd_dpi_panel_config_t dpi_cfg;
125	  memset(&dpi_cfg, 0, sizeof(dpi_cfg));
126	  dpi_cfg.virtual_channel = 0;
127	  dpi_cfg.dpi_clock_freq_mhz = 52.0f;
128	  dpi_cfg.video_timing.h_size = 1024;
129	  dpi_cfg.video_timing.v_size = 600;
130	  dpi_cfg.video_timing.hsync_pulse_width = 10;
131	  dpi_cfg.video_timing.hsync_back_porch = 120;
132	  dpi_cfg.video_timing.hsync_front_porch = 120;
133	  dpi_cfg.video_timing.vsync_pulse_width = 1;
134	  dpi_cfg.video_timing.vsync_back_porch = 20;
135	  dpi_cfg.video_timing.vsync_front_porch = 10;
136	
137	  ret = esp_lcd_new_panel_dpi(g_dsi_bus, &dpi_cfg, &g_dpi_panel);
138	  if (ret != 0)
139	    {
140	      syslog(LOG_ERR, "[DSI-FB] DPI panel create failed: %d\n", ret);
141	      return ret;
142	    }
143	
144	  /* 5. DMA start + video mode will be called AFTER Camera init
145	   * (Camera's esp_csi_dma_init resets GDMA, which would erase our config)
146	   */
147	
148	  syslog(LOG_INFO, "[DSI-FB] Phase 1 done (bus+panel created). "
149	         "Call esp_dsi_fb_start_refresh() after camera init.\n");
150	
151	  return 0;
152	}
