154	/****************************************************************************
155	 * Name: esp_dsi_fb_start_refresh
156	 *
157	 * Description:
158	 *   Start DMA refresh loop + video mode + backlight.
159	 *   MUST be called AFTER Camera CSI init (which resets GDMA).
160	 ****************************************************************************/
161	
162	int esp_dsi_fb_start_refresh(void)
163	{
164	  int ret;
165	
166	  if (g_dpi_panel == NULL)
167	    {
168	      return -EINVAL;
169	    }
170	
171	  /* Fill framebuffer with white for visual verification */
172	
173	  {
174	    uint8_t *fb = esp_lcd_dpi_panel_get_fb(g_dpi_panel);
175	    size_t fb_size = esp_lcd_dpi_panel_get_fb_size(g_dpi_panel);
176	    if (fb && fb_size > 0)
177	      {
178	        memset(fb, 0xFF, fb_size);  /* White = 0xFF for all RGB888 bytes */
179	        esp_cache_msync(fb, fb_size, ESP_CACHE_MSYNC_FLAG_DIR_C2M);
180	        syslog(LOG_INFO, "[DSI-FB] FB filled white (%zu bytes)\n", fb_size);
181	      }
182	  }
183	
184	  /* Start DMA -> video mode -> DPI output */
185	
186	  ret = esp_lcd_dpi_panel_init(g_dpi_panel);
187	  if (ret != 0)
188	    {
189	      syslog(LOG_ERR, "[DSI-FB] DPI panel init failed: %d\n", ret);
190	      return ret;
191	    }
192	
193	  /* Wait 200ms for stable video, then backlight */
194	
195	  usleep(200000);
196	  backlight_enable();
197	  syslog(LOG_INFO, "[DSI-FB] Backlight ON, display ready\n");
198	
199	  return 0;
200	}
