301	/****************************************************************************
302	 * Name: esp_lcd_dpi_panel_init
303	 *
304	 * Description:
305	 *   Start the DPI panel refresh loop.
306	 *   Critical sequence: start DMA → enable video mode → enable DPI output.
307	 ****************************************************************************/
308	
309	int esp_lcd_dpi_panel_init(esp_lcd_dpi_panel_handle_t panel)
310	{
311	  dw_gdma_block_transfer_config_t xfer;
312	  int ret;
313	
314	  if (!panel || !panel->fb)
315	    {
316	      return -EINVAL;
317	    }
318	
319	  /* Create DMA channel (must be done AFTER Camera CSI init which
320	   * resets GDMA and clears all channel configurations).
321	   */
322	
323	  dw_gdma_channel_alloc_config_t dma_cfg;
324	  memset(&dma_cfg, 0, sizeof(dma_cfg));
325	
326	  dma_cfg.src.block_transfer_type      = DW_GDMA_BLOCK_TRANSFER_LIST;
327	  dma_cfg.src.role                     = DW_GDMA_ROLE_MEM;
328	  dma_cfg.src.handshake_type           = DW_GDMA_HANDSHAKE_HW;
329	  dma_cfg.src.num_outstanding_requests = 5;
330	
331	  dma_cfg.dst.block_transfer_type      = DW_GDMA_BLOCK_TRANSFER_LIST;
332	  dma_cfg.dst.role                     = DW_GDMA_ROLE_PERIPH_DSI;
333	  dma_cfg.dst.handshake_type           = DW_GDMA_HANDSHAKE_HW;
334	  dma_cfg.dst.num_outstanding_requests = 2;
335	
336	  dma_cfg.flow_controller              = DW_GDMA_FLOW_CTRL_SELF;
337	  dma_cfg.chan_priority                 = 1;
338	
339	  ret = dw_gdma_new_channel(&dma_cfg, &panel->dma_chan);
340	  if (ret < 0)
341	    {
342	      syslog(LOG_ERR, "[DPI] Failed to create DMA channel: %d\n", ret);
343	      return ret;
344	    }
345	
346	  /* Create DMA link list (1 item, self-cycling) */
347	
348	  dw_gdma_link_list_config_t ll_cfg;
349	  memset(&ll_cfg, 0, sizeof(ll_cfg));
350	  ll_cfg.num_items = 1;
351	
352	  ret = dw_gdma_new_link_list(&ll_cfg, &panel->link_list);
353	  if (ret < 0)
354	    {
355	      syslog(LOG_ERR, "[DPI] Failed to create link list: %d\n", ret);
356	      return ret;
357	    }
358	
359	  /* Register DMA callback — not used with polling approach, skip */
360	
361	  /* Start the refresh polling thread */
362	
363	  panel->refresh_running = true;
364	  kthread_create("dsi_refresh", 200, 2048,
365	                 dsi_dma_refresh_thread, NULL);
366	
367	  /* Configure DMA transfer parameters in the LLI:
368	   *   Source: framebuffer in PSRAM/SRAM (incrementing)
369	   *   Dest:   Bridge FIFO at fixed address
370	   */
371	
372	  memset(&xfer, 0, sizeof(xfer));
373	
374	  xfer.src.addr       = (uint32_t)(uintptr_t)panel->fb;
375	  xfer.src.burst_mode = DW_GDMA_BURST_MODE_INCREMENT;
376	  xfer.src.burst_items = DW_GDMA_BURST_ITEMS_512;
377	  xfer.src.burst_len  = 16;
378	  xfer.src.width      = DW_GDMA_TRANS_WIDTH_64;
379	
380	  xfer.dst.addr       = MIPI_DSI_BRG_MEM_BASE;
381	  xfer.dst.burst_mode = DW_GDMA_BURST_MODE_FIXED;
382	  xfer.dst.burst_items = DW_GDMA_BURST_ITEMS_256;
383	  xfer.dst.burst_len  = 16;
384	  xfer.dst.width      = DW_GDMA_TRANS_WIDTH_64;
385	
386	  /* Size in 64-bit transfer items */
387	
388	  xfer.size = panel->fb_size * 8 / 64;
389	
390	  dw_gdma_lli_config_transfer(
391	      dw_gdma_link_list_get_item(panel->link_list, 0), &xfer);
392	
393	  /* Mark LLI as valid and last. DMA will complete one frame then stop.
394	   * CSI ISR calls esp_dsi_dma_isr_handler() to re-arm for next frame.
395	   */
396	
397	  dw_gdma_block_markers_t markers;
398	  markers.is_valid = true;
399	  markers.is_last  = true;
400	
401	  dw_gdma_lli_set_block_markers(
402	      dw_gdma_link_list_get_item(panel->link_list, 0), markers);
403	
404	  /* Attach link list and start DMA */
405	
406	  dw_gdma_channel_use_link_list(panel->dma_chan, panel->link_list);
407	  dw_gdma_channel_enable_ctrl(panel->dma_chan, true);
408	
409	  /* Enable video mode — THIS triggers the PHY LP→HS transition */
410	
411	  mipi_dsi_host_ll_enable_video_mode(panel->bus->hal.host, true);
412	
413	  /* Enable DPI output on the bridge */
414	
415	  mipi_dsi_brg_ll_enable_dpi_output(panel->bus->hal.bridge, true);
416	  mipi_dsi_brg_ll_update_dpi_config(panel->bus->hal.bridge);
417	
418	  /* Inline re-arm loop: keep DMA running for first 5 seconds
419	   * to verify display works before handing off to refresh thread.
420	   */
421	
422	  {
423	    dw_gdma_dev_t *dev = DW_GDMA_LL_GET_HW(0);
424	    int frames = 0;
425	    for (int i = 0; i < 300; i++)  /* 300 * 16ms = ~5 seconds */
426	      {
427	        usleep(16000);
428	        uint32_t chen = dev->chen0.val;
429	        if (!(chen & (1u << 1)))
430	          {
431	            /* Channel idle — re-arm */
432	
433	            uint32_t st = dw_gdma_ll_channel_get_intr_status(dev, 1);
434	            if (st)
435	              {
436	                dw_gdma_ll_channel_clear_intr(dev, 1, st);
437	              }
438	
439	            dw_gdma_block_markers_t m2;
440	            m2.is_valid = true;
441	            m2.is_last  = true;
442	            dw_gdma_lli_set_block_markers(
443	                dw_gdma_link_list_get_item(panel->link_list, 0), m2);
444	            dw_gdma_channel_use_link_list(panel->dma_chan,
445	                                          panel->link_list);
446	            dw_gdma_channel_enable_ctrl(panel->dma_chan, true);
447	            frames++;
448	          }
449	      }
450	
451	    syslog(LOG_INFO, "[DPI] Inline re-arm: %d frames in 5s\n", frames);
452	  }
453	
454	  syslog(LOG_INFO, "[DPI] Init: DMA started, video mode active\n");
455	  return 0;
456	}
