261	  items_nc = (dw_gdma_link_list_item_t *)DW_GDMA_NON_CACHE_ADDR(items);
262	
263	  /* For a single-item list, set up self-cycling (next points to self) */
264	
265	  if (config->num_items == 1)
266	    {
267	      dw_gdma_ll_lli_set_next_item_addr(items_nc, (uint32_t)items);
