316	/****************************************************************************
317	 * Name: dw_gdma_lli_config_transfer
318	 ****************************************************************************/
319	
320	int dw_gdma_lli_config_transfer(
321	    dw_gdma_link_list_item_t *lli,
322	    const dw_gdma_block_transfer_config_t *config)
323	{
324	  if (lli == NULL || config == NULL)
325	    {
326	      return -EINVAL;
327	    }
328	
329	  /* Set source and destination addresses */
330	
331	  dw_gdma_ll_lli_set_src_addr(lli, config->src.addr);
332	  dw_gdma_ll_lli_set_dst_addr(lli, config->dst.addr);
333	
334	  /* Set master ports based on addresses */
335	
336	  dw_gdma_ll_lli_set_src_master_port(lli, config->src.addr);
337	  dw_gdma_ll_lli_set_dst_master_port(lli, config->dst.addr);
338	
339	  /* Set block transfer size */
340	
341	  dw_gdma_ll_lli_set_trans_block_size(lli, config->size);
342	
343	  /* Set source burst parameters */
344	
345	  dw_gdma_ll_lli_set_src_burst_mode(lli, config->src.burst_mode);
346	  dw_gdma_ll_lli_set_src_burst_items(lli, config->src.burst_items);
347	  dw_gdma_ll_lli_set_src_burst_len(lli, config->src.burst_len);
348	  dw_gdma_ll_lli_set_src_trans_width(lli, config->src.width);
349	
350	  /* Set destination burst parameters */
351	
352	  dw_gdma_ll_lli_set_dst_burst_mode(lli, config->dst.burst_mode);
353	  dw_gdma_ll_lli_set_dst_burst_items(lli, config->dst.burst_items);
354	  dw_gdma_ll_lli_set_dst_burst_len(lli, config->dst.burst_len);
355	  dw_gdma_ll_lli_set_dst_trans_width(lli, config->dst.width);
356	
357	  return 0;
358	}
