448	/****************************************************************************
449	 * Name: esp_dsi_dma_isr_handler
450	 *
451	 * Description:
452	 *   Called from the shared DW-GDMA ISR (in esp_mipi_csi.c) when channel 1
453	 *   has pending interrupt status. Clears the interrupt and invokes the
454	 *   registered trans_done callback to re-arm DMA for continuous refresh.
455	 ****************************************************************************/
456	
457	void esp_dsi_dma_isr_handler(void)
458	{
459	  struct dw_gdma_channel_t *chan = &g_dsi_channel;
460	  dw_gdma_dev_t *dev = chan->dev;
461	  int ch = chan->chan_id;
462	  uint32_t status;
463	
464	  if (!g_dsi_channel_allocated || dev == NULL)
465	    {
466	      return;
467	    }
468	
469	  /* Read and clear channel 1 interrupt status */
470	
471	  status = dw_gdma_ll_channel_get_intr_status(dev, ch);
472	  if (status == 0)
473	    {
474	      return;
475	    }
476	
477	  dw_gdma_ll_channel_clear_intr(dev, ch, status);
478	
479	  /* If block transfer done, invoke callback to re-arm DMA */
480	
481	  if (chan->on_block_trans_done)
482	    {
483	      dw_gdma_trans_done_event_data_t ev;
484	      memset(&ev, 0, sizeof(ev));
485	      chan->on_block_trans_done(chan, &ev, chan->user_data);
486	    }
487	}
