6	#include <math.h>
7	#include "esp_lcd_mipi_dsi.h"
8	#include "esp_clk_tree.h"
9	#include "mipi_dsi_priv.h"
10	
11	#define MIPI_DSI_DEFAULT_TIMEOUT_CLOCK_FREQ_MHZ 10
12	// TxClkEsc frequency must be configured between 2 and 20 MHz
13	#define MIPI_DSI_DEFAULT_ESCAPE_CLOCK_FREQ_MHZ  18
14	
15	esp_err_t esp_lcd_new_dsi_bus(const esp_lcd_dsi_bus_config_t *bus_config, esp_lcd_dsi_bus_handle_t *ret_bus)
16	{
17	    esp_err_t ret = ESP_OK;
18	    ESP_RETURN_ON_FALSE(bus_config && ret_bus, ESP_ERR_INVALID_ARG, TAG, "invalid argument");
19	    ESP_RETURN_ON_FALSE(bus_config->num_data_lanes <= MIPI_DSI_LL_MAX_DATA_LANES,
20	                        ESP_ERR_INVALID_ARG, TAG, "invalid number of data lanes %d", bus_config->num_data_lanes);
21	    ESP_RETURN_ON_FALSE(bus_config->lane_bit_rate_mbps >= MIPI_DSI_LL_MIN_PHY_MBPS &&
22	                        bus_config->lane_bit_rate_mbps <= MIPI_DSI_LL_MAX_PHY_MBPS, ESP_ERR_INVALID_ARG, TAG,
23	                        "invalid lane bit rate %.2f", bus_config->lane_bit_rate_mbps);
24	
25	    // we don't use an bus allocator here, because different DSI bus uses different PHY.
26	    // And each PHY has its own associated PINs, which is not changeable.
27	    // So user HAS TO specify the bus ID by themselves, according to their PCB design.
28	    int bus_id = bus_config->bus_id;
29	    ESP_RETURN_ON_FALSE(bus_id >= 0 && bus_id < MIPI_DSI_LL_GET(BUS_NUM), ESP_ERR_INVALID_ARG, TAG, "invalid bus ID %d", bus_id);
30	    esp_lcd_dsi_bus_t *dsi_bus = heap_caps_calloc(1, sizeof(esp_lcd_dsi_bus_t), DSI_MEM_ALLOC_CAPS);
31	    ESP_RETURN_ON_FALSE(dsi_bus, ESP_ERR_NO_MEM, TAG, "no memory for DSI bus");
32	    dsi_bus->bus_id = bus_id;
33	
34	    // Enable the APB clock for accessing the DSI host and bridge registers
35	    PERIPH_RCC_ATOMIC() {
36	        mipi_dsi_ll_enable_bus_clock(bus_id, true);
37	        mipi_dsi_ll_reset_register(bus_id);
38	    }
39	
40	    // if the clock source is not assigned, fallback to the default clock source
41	    mipi_dsi_phy_pllref_clock_source_t phy_clk_src = bus_config->phy_clk_src;
42	    if (phy_clk_src == 0) {
43	#if SOC_IS(ESP32P4) && HAL_CONFIG(CHIP_SUPPORT_MIN_REV) < 300
44	        phy_clk_src = MIPI_DSI_PHY_PLLREF_CLK_SRC_DEFAULT_LEGACY;
45	#else
46	        phy_clk_src = MIPI_DSI_PHY_PLLREF_CLK_SRC_DEFAULT;
47	#endif
48	    }
49	    ESP_GOTO_ON_ERROR(esp_clk_tree_enable_src((soc_module_clk_t)phy_clk_src, true), err, TAG, "clock source enable failed");
50	
51	    // always use the default clock source for the DSI PHY configuration
52	    ESP_GOTO_ON_ERROR(esp_clk_tree_enable_src((soc_module_clk_t)MIPI_DSI_PHY_CFG_CLK_SRC_DEFAULT, true), err, TAG, "clock source enable failed");
53	
54	    // enable the clock source for DSI PHY
55	    PERIPH_RCC_ATOMIC() {
56	        // set the DSI PHY configuration clock
57	        // the configuration clock is used for all modes except the shutdown mode
58	        mipi_dsi_ll_set_phy_config_clock_source(bus_id, MIPI_DSI_PHY_CFG_CLK_SRC_DEFAULT);
59	        mipi_dsi_ll_enable_phy_config_clock(bus_id, true);
60	        // set the DSI PHY PLL reference clock
61	        mipi_dsi_ll_set_phy_pllref_clock_source(bus_id, phy_clk_src);
62	        mipi_dsi_ll_set_phy_pll_ref_clock_div(bus_id, 1); // no division
63	        mipi_dsi_ll_enable_phy_pllref_clock(bus_id, true);
64	    }
65	
66	#if CONFIG_PM_ENABLE
67	    // When MIPI DSI is working, we don't expect the clock source would be turned off
68	    esp_pm_lock_type_t pm_lock_type = ESP_PM_NO_LIGHT_SLEEP;
69	    ret  = esp_pm_lock_create(pm_lock_type, 0, "dsi_phy", &dsi_bus->pm_lock);
70	    ESP_GOTO_ON_ERROR(ret, err, TAG, "create PM lock failed");
71	    // before we configure the PLL, we want the clock source to be stable
72	    esp_pm_lock_acquire(dsi_bus->pm_lock);
73	#endif
74	
75	    // if the number of data lanes is not assigned, fallback to the maximum number of data lanes
76	    int num_data_lanes = bus_config->num_data_lanes;
77	    if (num_data_lanes == 0) {
78	        num_data_lanes = MIPI_DSI_LL_MAX_DATA_LANES;
79	    }
80	    // initialize HAL context
81	    mipi_dsi_hal_config_t hal_config = {
82	        .bus_id = bus_id,
83	        .lane_bit_rate_mbps = bus_config->lane_bit_rate_mbps,
84	        .num_data_lanes = num_data_lanes,
85	    };
86	    mipi_dsi_hal_init(&dsi_bus->hal, &hal_config);
87	    mipi_dsi_hal_context_t *hal = &dsi_bus->hal;
88	
89	    // get the frequency of the PHY clock source
90	    uint32_t phy_clk_src_freq_hz = 0;
91	    ESP_GOTO_ON_ERROR(esp_clk_tree_src_get_freq_hz(phy_clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED,
92	                                                   &phy_clk_src_freq_hz), err, TAG, "get phy clock source frequency failed");
93	    // configure the PHY PLL
94	    mipi_dsi_hal_configure_phy_pll(hal, phy_clk_src_freq_hz, bus_config->lane_bit_rate_mbps);
95	
96	    // wait for PHY initialization done
97	    while (!mipi_dsi_phy_ll_is_pll_locked(hal->host)) {
98	        vTaskDelay(pdMS_TO_TICKS(1));
99	    }
100	    while (!mipi_dsi_phy_ll_are_lanes_stopped(hal->host, num_data_lanes)) {
101	        vTaskDelay(pdMS_TO_TICKS(1));
102	    }
103	
104	    // initialize the DSI operation mode: command mode
105	    mipi_dsi_host_ll_enable_video_mode(hal->host, false);
106	    // set clock lane state: force HS keeps clock in high-speed mode continuously, auto lets the DSI host manage transitions
107	    mipi_dsi_host_ll_set_clock_lane_state(hal->host, bus_config->flags.clock_lane_force_hs ? MIPI_DSI_LL_CLOCK_LANE_STATE_HS : MIPI_DSI_LL_CLOCK_LANE_STATE_AUTO);
108	    // Set the time that is required by the clock and data lanes to go from high-speed to low-power and from low-power to high-speed
109	    mipi_dsi_phy_ll_set_switch_time(hal->host, 50, 104, 46, 128);
110	
111	    // enable CRC reception and ECC reception, error correction, and reporting
112	    mipi_dsi_host_ll_enable_rx_crc(hal->host, true);
113	    mipi_dsi_host_ll_enable_rx_ecc(hal->host, true);
114	    // enable sending the EoTp packet at the end of each transmission for HS mode
115	    mipi_dsi_host_ll_enable_tx_eotp(hal->host, true, false);
116	
117	    // Set the divider to get the Time Out clock, clock source is the high-speed byte clock
118	    mipi_dsi_host_ll_set_timeout_clock_division(hal->host, (uint32_t)roundf(bus_config->lane_bit_rate_mbps / 8.0f / MIPI_DSI_DEFAULT_TIMEOUT_CLOCK_FREQ_MHZ));
119	    // Set the divider to get the TX Escape clock, clock source is the high-speed byte clock
120	    mipi_dsi_host_ll_set_escape_clock_division(hal->host, (uint32_t)roundf(bus_config->lane_bit_rate_mbps / 8.0f / MIPI_DSI_DEFAULT_ESCAPE_CLOCK_FREQ_MHZ));
121	    // set the timeout intervals to zero, means to disable the timeout mechanism
122	    mipi_dsi_host_ll_set_timeout_count(hal->host, 0, 0, 0, 0, 0, 0, 0);
123	    // DSI host will wait indefinitely for a read response from the DSI device
124	    mipi_dsi_phy_ll_set_max_read_time(hal->host, 6000);
125	    // set how long the DSI host will wait before sending the next transmission
126	    mipi_dsi_phy_ll_set_stop_wait_time(hal->host, 0x3F);
127	
128	    *ret_bus = dsi_bus;
129	    return ESP_OK;
130	err:
131	    if (dsi_bus) {
132	        esp_lcd_del_dsi_bus(dsi_bus);
133	    }
134	    return ret;
135	}
136	
137	esp_err_t esp_lcd_del_dsi_bus(esp_lcd_dsi_bus_handle_t bus)
138	{
139	    ESP_RETURN_ON_FALSE(bus, ESP_ERR_INVALID_ARG, TAG, "invalid argument");
140	    int bus_id = bus->bus_id;
141	    // disable the clock source for DSI PHY
142	    PERIPH_RCC_ATOMIC() {
143	        mipi_dsi_ll_enable_phy_pllref_clock(bus_id, false);
144	        mipi_dsi_ll_enable_phy_config_clock(bus_id, false);
145	    }
146	    // disable the APB clock for accessing the DSI peripheral registers
147	    PERIPH_RCC_ATOMIC() {
148	        mipi_dsi_ll_enable_bus_clock(bus_id, false);
149	    }
150	#if CONFIG_PM_ENABLE
151	    if (bus->pm_lock) {
152	        esp_pm_lock_release(bus->pm_lock);
153	        esp_pm_lock_delete(bus->pm_lock);
154	    }
155	#endif
156	    free(bus);
157	    return ESP_OK;
158	}
