26	struct esp_lcd_dpi_panel_t {
27	    esp_lcd_panel_t base;         // Base class of generic lcd panel
28	    esp_lcd_dsi_bus_handle_t bus; // DSI bus handle
29	    uint8_t virtual_channel;      // Virtual channel ID, index from 0
30	    uint8_t cur_fb_index;         // Current frame buffer index
31	    uint8_t num_fbs;              // Number of frame buffers
32	    uint8_t *fbs[DPI_PANEL_MAX_FB_NUM]; // Frame buffers
33	    uint32_t h_pixels;            // Horizontal pixels
34	    uint32_t v_pixels;            // Vertical pixels
