39	    dw_gdma_channel_handle_t dma_chan;   // DMA channel
40	    intr_handle_t brg_intr;              // DSI Bridge interrupt handle
41	    dw_gdma_link_list_handle_t link_lists[DPI_PANEL_MAX_FB_NUM]; // DMA link list
42	
43	    // hook fields
44	    esp_lcd_panel_draw_bitmap_hook_t draw_bitmap_hook; // Draw bitmap hook function
45	    void* hook_ctx; // Hook context
46	    bool (*on_hook_end)(esp_lcd_panel_handle_t panel); // Callback to be invoked when the draw bitmap hook completes its operation
47	    esp_async_fbcpy_handle_t fbcpy_handle; // Use DMA2D to do frame buffer copy (only when using DMA2D draw bitmap hook)
48	    SemaphoreHandle_t draw_sem;            // A semaphore used to synchronize the draw operations when DMA2D is used
49	
50	#if CONFIG_PM_ENABLE
51	    esp_pm_lock_handle_t pm_lock;          // Power management lock
52	#endif
53	    esp_lcd_dpi_panel_color_trans_done_cb_t on_color_trans_done; // Callback invoked when color data transfer has finished
54	    esp_lcd_dpi_panel_refresh_done_cb_t on_refresh_done; // Callback invoked when one refresh operation finished (kinda like a vsync end)
55	    void *user_ctx; // User context for the callback
56	};
