58	static bool dpi_panel_draw_bitmap_hook_end(esp_lcd_panel_t *panel)
59	{
60	    esp_lcd_dpi_panel_t *dpi_panel = __containerof(panel, esp_lcd_dpi_panel_t, base);
61	    if (dpi_panel->on_color_trans_done) {
62	        return dpi_panel->on_color_trans_done(panel, NULL, dpi_panel->user_ctx);
63	    }
64	    return false;
