67	static bool async_fbcpy_done_cb(esp_async_fbcpy_handle_t mcp, esp_async_fbcpy_event_data_t *event, void *cb_args)
68	{
69	    bool need_yield = false;
70	    esp_lcd_dpi_panel_t *dpi_panel = (esp_lcd_dpi_panel_t *)cb_args;
71	
72	    // release the draw semaphore first
73	    BaseType_t task_woken = pdFALSE;
74	    xSemaphoreGiveFromISR(dpi_panel->draw_sem, &task_woken);
75	    if (task_woken == pdTRUE) {
76	        need_yield = true;
77	    }
78	
79	    if (dpi_panel->on_hook_end) {
80	        if (dpi_panel->on_hook_end(&dpi_panel->base)) {
81	            need_yield = true;
82	        }
83	    }
84	
85	    return need_yield;
86	}
87	
88	bool mipi_dsi_dma_trans_done_cb(dw_gdma_channel_handle_t chan, const dw_gdma_trans_done_event_data_t *event_data, void *user_data)
89	{
90	    bool yield_needed = false;
91	    esp_lcd_dpi_panel_t *dpi_panel = (esp_lcd_dpi_panel_t *)user_data;
92	    uint8_t fb_index = dpi_panel->cur_fb_index;
93	    dw_gdma_link_list_handle_t link_list = dpi_panel->link_lists[fb_index];
94	
95	    // restart the DMA transfer, keep refreshing the LCD
96	    dw_gdma_block_markers_t markers = {
97	        .is_valid = true,
98	        .is_last = true,
99	    };
100	    dw_gdma_lli_set_block_markers(dw_gdma_link_list_get_item(link_list, 0), markers);
101	    dw_gdma_channel_use_link_list(chan, link_list);
102	    dw_gdma_channel_enable_ctrl(chan, true);
103	
104	#if !MIPI_DSI_BRG_LL_EVENT_VSYNC
105	    // the DMA descriptor is large enough to carry a whole frame buffer, so this event can also be treated as a fake "vsync end"
106	    if (dpi_panel->on_refresh_done) {
107	        if (dpi_panel->on_refresh_done(&dpi_panel->base, NULL, dpi_panel->user_ctx)) {
108	            yield_needed = true;
109	        }
110	    }
111	#endif
112	    return yield_needed;
113	}
114	
115	void mipi_dsi_bridge_isr_handler(void *args)
116	{
117	    esp_lcd_dpi_panel_t* dpi_panel = (esp_lcd_dpi_panel_t *)args;
118	    mipi_dsi_hal_context_t *hal = &dpi_panel->bus->hal;
119	    // clear the interrupt status
120	    uint32_t intr_status = mipi_dsi_brg_ll_get_interrupt_status(hal->bridge);
121	    mipi_dsi_brg_ll_clear_interrupt_status(hal->bridge, intr_status);
122	
123	    if (intr_status & MIPI_DSI_BRG_LL_EVENT_UNDERRUN) {
124	        // when an underrun happens, the LCD display may already becomes blue
125	        // it's too late to recover the display, so we just print an error message
126	        // as a hint to the user that he should optimize the memory bandwidth (with AXI-ICM)
127	        ESP_DRAM_LOGE(TAG, "can't fetch data from external memory fast enough, underrun happens");
128	    }
129	    if (intr_status & MIPI_DSI_BRG_LL_EVENT_VSYNC) {
130	        if (dpi_panel->on_refresh_done) {
131	            if (dpi_panel->on_refresh_done(&dpi_panel->base, NULL, dpi_panel->user_ctx)) {
132	                portYIELD_FROM_ISR();
133	            }
134	        }
135	    }
136	}
