138	// Please note, errors happened in this function is just propagated to the caller
139	// dpi_panel_del() is actually doing the error handling
140	static esp_err_t dpi_panel_create_dma_link(esp_lcd_dpi_panel_t *dpi_panel)
141	{
142	    dw_gdma_channel_handle_t dma_chan = NULL;
143	    dw_gdma_link_list_handle_t link_list = NULL;
144	    // sending image stream from memory to the DSI bridge
145	    dw_gdma_channel_alloc_config_t dma_alloc_config = {
146	        .src = {
147	            .block_transfer_type = DW_GDMA_BLOCK_TRANSFER_LIST,
148	            .role = DW_GDMA_ROLE_MEM,
149	            .handshake_type = DW_GDMA_HANDSHAKE_HW,
150	            .num_outstanding_requests = 5,
151	        },
152	        .dst = {
153	            .block_transfer_type = DW_GDMA_BLOCK_TRANSFER_LIST,
154	            .role = DW_GDMA_ROLE_PERIPH_DSI,
155	            .handshake_type = DW_GDMA_HANDSHAKE_HW,
156	            .num_outstanding_requests = 2,
157	        },
158	        .flow_controller = DW_GDMA_FLOW_CTRL_SELF, // DMA as the flow controller
159	        .chan_priority = 1,
160	    };
161	    ESP_RETURN_ON_ERROR(dw_gdma_new_channel(&dma_alloc_config, &dma_chan), TAG, "create DMA channel failed");
162	    dpi_panel->dma_chan = dma_chan;
163	
164	    // create DMA link lists
165	    dw_gdma_link_list_config_t link_list_config = {
166	        .num_items = DPI_PANEL_MIN_DMA_NODES_PER_LINK,
167	        .link_type = DW_GDMA_LINKED_LIST_TYPE_SINGLY,
168	    };
169	    for (int i = 0; i < dpi_panel->num_fbs; i++) {
170	        ESP_RETURN_ON_ERROR(dw_gdma_new_link_list(&link_list_config, &link_list), TAG, "create DMA link list failed");
171	        dpi_panel->link_lists[i] = link_list;
172	    }
173	
174	    // register DMA ISR callbacks
175	    dw_gdma_event_callbacks_t dsi_dma_cbs = {
176	        .on_full_trans_done = mipi_dsi_dma_trans_done_cb,
177	    };
178	    ESP_RETURN_ON_ERROR(dw_gdma_channel_register_event_callbacks(dma_chan, &dsi_dma_cbs, dpi_panel), TAG, "register DMA callbacks failed");
179	
180	    return ESP_OK;
181	}
