183	esp_err_t esp_lcd_new_panel_dpi(esp_lcd_dsi_bus_handle_t bus, const esp_lcd_dpi_panel_config_t *panel_config, esp_lcd_panel_handle_t *ret_panel)
184	{
185	    esp_err_t ret = ESP_OK;
186	    esp_lcd_dpi_panel_t *dpi_panel = NULL;
187	    ESP_RETURN_ON_FALSE(bus && panel_config && ret_panel, ESP_ERR_INVALID_ARG, TAG, "invalid argument");
188	    ESP_RETURN_ON_FALSE(panel_config->virtual_channel < 4, ESP_ERR_INVALID_ARG, TAG, "invalid virtual channel %d", panel_config->virtual_channel);
189	    ESP_RETURN_ON_FALSE(panel_config->dpi_clock_freq_mhz > 0, ESP_ERR_INVALID_ARG, TAG, "invalid DPI clock frequency %.2f", panel_config->dpi_clock_freq_mhz);
190	
191	    size_t num_fbs = panel_config->num_fbs;
192	    // if the user doesn't specify the number of frame buffers, then fallback to use one frame buffer
193	    if (num_fbs == 0) {
194	        num_fbs = 1;
195	    }
196	    ESP_RETURN_ON_FALSE(num_fbs <= DPI_PANEL_MAX_FB_NUM, ESP_ERR_INVALID_ARG, TAG, "num_fbs not within [1,%d]", DPI_PANEL_MAX_FB_NUM);
197	
198	    // by default, use RGB888 as the input color format
199	    lcd_color_format_t in_color_format = LCD_COLOR_FMT_RGB888;
200	    // override in_color_format if specified by the user
201	    if (panel_config->in_color_format) {
202	        in_color_format = panel_config->in_color_format;
203	    }
204	    size_t bits_per_pixel = color_hal_pixel_format_fourcc_get_bit_depth(in_color_format);
205	    // by default, out_color_format is the same as in_color_format (i.e. no color format conversion)
206	    lcd_color_format_t out_color_format = in_color_format;
207	    if (panel_config->out_color_format) {
208	        out_color_format = panel_config->out_color_format;
209	    }
210	    ESP_RETURN_ON_FALSE(panel_config->video_timing.h_size * panel_config->video_timing.v_size * bits_per_pixel % 8 == 0,
211	                        ESP_ERR_INVALID_ARG, TAG, "frame buffer size not aligned to byte boundary");
212	
213	    int bus_id = bus->bus_id;
214	    mipi_dsi_hal_context_t *hal = &bus->hal;
215	
216	    dpi_panel = heap_caps_calloc(1, sizeof(esp_lcd_dpi_panel_t), DSI_MEM_ALLOC_CAPS);
217	    ESP_GOTO_ON_FALSE(dpi_panel, ESP_ERR_NO_MEM, err, TAG, "no memory for DPI panel");
218	    dpi_panel->virtual_channel = panel_config->virtual_channel;
219	    dpi_panel->in_color_format = in_color_format;
220	    dpi_panel->out_color_format = out_color_format;
221	    dpi_panel->bus = bus;
222	    dpi_panel->num_fbs = num_fbs;
223	
224	    // allocate frame buffer from PSRAM
225	    size_t fb_size = panel_config->video_timing.h_size * panel_config->video_timing.v_size * bits_per_pixel / 8;
226	    for (int i = 0; i < num_fbs; i++) {
227	        uint8_t *frame_buffer = heap_caps_calloc(1, fb_size, MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT | MALLOC_CAP_DMA);
228	        ESP_GOTO_ON_FALSE(frame_buffer, ESP_ERR_NO_MEM, err, TAG, "no memory for frame buffer");
229	        dpi_panel->fbs[i] = frame_buffer;
230	        ESP_LOGD(TAG, "fb[%d] @%p", i, frame_buffer);
231	        // preset the frame buffer with black color
232	        // the frame buffer address alignment is ensured by `heap_caps_calloc`
233	        // while the value of the fb_size may not be aligned to the cache line size
234	        // but that's not a problem because the `heap_caps_calloc` internally allocated a buffer whose size is aligned up to the cache line size
235	        ESP_GOTO_ON_ERROR(esp_cache_msync(frame_buffer, fb_size, ESP_CACHE_MSYNC_FLAG_DIR_C2M | ESP_CACHE_MSYNC_FLAG_UNALIGNED),
236	                          err, TAG, "cache write back failed");
237	    }
238	    dpi_panel->fb_size = fb_size;
239	    dpi_panel->bits_per_pixel = bits_per_pixel;
240	    dpi_panel->h_pixels = panel_config->video_timing.h_size;
241	    dpi_panel->v_pixels = panel_config->video_timing.v_size;
242	
243	    // if the clock source is not assigned, fallback to the default clock source
244	    mipi_dsi_dpi_clock_source_t dpi_clk_src = panel_config->dpi_clk_src;
245	    if (dpi_clk_src == 0) {
246	        dpi_clk_src = MIPI_DSI_DPI_CLK_SRC_DEFAULT;
247	    }
248	    // get the clock source frequency
249	    uint32_t dpi_clk_src_freq_hz = 0;
250	    ESP_GOTO_ON_ERROR(esp_clk_tree_src_get_freq_hz(dpi_clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED,
251	                                                   &dpi_clk_src_freq_hz), err, TAG, "get clock source frequency failed");
252	    // divide the source clock to get the final DPI clock
253	    float dpi_clk_src_freq_mhz = (float)dpi_clk_src_freq_hz / 1000.0f / 1000.0f;
254	    uint32_t dpi_div = mipi_dsi_hal_host_dpi_calculate_divider(hal, dpi_clk_src_freq_mhz, panel_config->dpi_clock_freq_mhz);
255	    ESP_GOTO_ON_ERROR(esp_clk_tree_enable_src((soc_module_clk_t)dpi_clk_src, true), err, TAG, "clock source enable failed");
256	    // set the clock source, set the divider, and enable the dpi clock
257	    PERIPH_RCC_ATOMIC() {
258	        mipi_dsi_ll_set_dpi_clock_source(bus_id, dpi_clk_src);
259	        mipi_dsi_ll_set_dpi_clock_div(bus_id, dpi_div);
260	        mipi_dsi_ll_enable_dpi_clock(bus_id, true);
261	    }
262	
263	#if CONFIG_PM_ENABLE
264	    // When MIPI DSI is working, we don't expect the clock source would be turned off
265	    // use CPU_MAX lock to ensure PSRAM bandwidth and usability during DFS
266	    esp_pm_lock_type_t pm_lock_type = ESP_PM_CPU_FREQ_MAX;
267	    ret  = esp_pm_lock_create(pm_lock_type, 0, "dsi_dpi", &dpi_panel->pm_lock);
268	    ESP_GOTO_ON_ERROR(ret, err, TAG, "create PM lock failed");
269	    esp_pm_lock_acquire(dpi_panel->pm_lock);
270	#endif
271	
272	    // install interrupt service
273	    int isr_flags = ESP_INTR_FLAG_LOWMED;
274	#if CONFIG_LCD_DSI_ISR_CACHE_SAFE
275	    isr_flags |= ESP_INTR_FLAG_IRAM;
276	#endif
277	    ESP_GOTO_ON_ERROR(esp_intr_alloc(soc_mipi_dsi_signals[bus_id].brg_irq_id, isr_flags, mipi_dsi_bridge_isr_handler,
278	                                     dpi_panel, &dpi_panel->brg_intr), err, TAG, "allocate DSI Bridge interrupt failed");
279	
280	    // create DMA resources
281	    ESP_GOTO_ON_ERROR(dpi_panel_create_dma_link(dpi_panel), err, TAG, "initialize DMA link failed");
282	
283	    mipi_dsi_host_ll_dpi_set_vcid(hal->host, panel_config->virtual_channel);
284	    mipi_dsi_host_ll_dpi_set_color_coding(hal->host, out_color_format, 0);
285	    // these signals define how the DPI interface interacts with the controller
286	    mipi_dsi_host_ll_dpi_set_timing_polarity(hal->host, false, false, false, false, false);
287	
288	    if (panel_config->flags.disable_lp) {
289	        // configure the low-power transitions: defines the video periods which are NOT permitted to goto low-power
290	        mipi_dsi_host_ll_dpi_enable_lp_horizontal_timing(hal->host, false, false);
291	        mipi_dsi_host_ll_dpi_enable_lp_vertical_timing(hal->host, false, false, false, false);
292	        // commands are NOT transmitted in low-power mode
293	        mipi_dsi_host_ll_dpi_enable_lp_command(hal->host, false);
294	    } else {
295	        // configure the low-power transitions: defines the video periods which are permitted to goto low-power if the time available to do so
296	        mipi_dsi_host_ll_dpi_enable_lp_horizontal_timing(hal->host, true, true);
297	        mipi_dsi_host_ll_dpi_enable_lp_vertical_timing(hal->host, true, true, true, true);
298	        // commands are transmitted in low-power mode
299	        mipi_dsi_host_ll_dpi_enable_lp_command(hal->host, true);
300	    }
301	    // after sending a frame, the DSI device should return an ack
302	    mipi_dsi_host_ll_dpi_enable_frame_ack(hal->host, true);
303	    // using the burst mode because it's energy-efficient
304	    mipi_dsi_host_ll_dpi_set_video_burst_type(hal->host, MIPI_DSI_LL_VIDEO_BURST_WITH_SYNC_PULSES);
305	    // configure the size of the active lin period, measured in pixels
306	    mipi_dsi_host_ll_dpi_set_video_packet_pixel_num(hal->host, panel_config->video_timing.h_size);
307	    // disable multi-packets
308	    mipi_dsi_host_ll_dpi_set_trunks_num(hal->host, 0);
309	    // disable "null packets"
310	    mipi_dsi_host_ll_dpi_set_null_packet_size(hal->host, 0);
311	    // set horizontal and vertical timing configuration
312	    mipi_dsi_hal_host_dpi_set_horizontal_timing(hal, panel_config->video_timing.hsync_pulse_width,
313	                                                panel_config->video_timing.hsync_back_porch,
314	                                                panel_config->video_timing.h_size,
315	                                                panel_config->video_timing.hsync_front_porch);
316	    mipi_dsi_hal_host_dpi_set_vertical_timing(hal, panel_config->video_timing.vsync_pulse_width,
317	                                              panel_config->video_timing.vsync_back_porch,
318	                                              panel_config->video_timing.v_size,
319	                                              panel_config->video_timing.vsync_front_porch);
320	    mipi_dsi_brg_ll_set_num_pixel_bits(hal->bridge, panel_config->video_timing.h_size * panel_config->video_timing.v_size * bits_per_pixel);
321	    mipi_dsi_brg_ll_set_underrun_discard_count(hal->bridge, panel_config->video_timing.h_size);
322	    // set the in/out color formats in the DSI bridge
323	    mipi_dsi_brg_ll_set_input_color_format(hal->bridge, in_color_format);
324	    mipi_dsi_brg_ll_set_output_color_format(hal->bridge, out_color_format, 0);
325	    // use the DW_GDMA as the flow controller
326	    mipi_dsi_brg_ll_set_flow_controller(hal->bridge, MIPI_DSI_LL_FLOW_CONTROLLER_DMA);
327	    mipi_dsi_brg_ll_set_multi_block_number(hal->bridge, DPI_PANEL_MIN_DMA_NODES_PER_LINK);
328	    mipi_dsi_brg_ll_set_burst_len(hal->bridge, 256);
329	    mipi_dsi_brg_ll_set_empty_threshold(hal->bridge, 1024 - 256);
330	    // enable DSI bridge
331	    mipi_dsi_brg_ll_enable(hal->bridge, true);
332	    mipi_dsi_brg_ll_update_dpi_config(hal->bridge);
333	
334	    dpi_panel->base.del = dpi_panel_del;
335	    dpi_panel->base.init = dpi_panel_init;
336	    dpi_panel->base.draw_bitmap = dpi_panel_draw_bitmap;
337	    dpi_panel->base.draw_bitmap_2d = dpi_panel_draw_bitmap_2d;
338	    *ret_panel = &dpi_panel->base;
339	    ESP_LOGD(TAG, "dpi panel created @%p", dpi_panel);
340	    return ESP_OK;
341	err:
342	    if (dpi_panel) {
343	        dpi_panel_del(&dpi_panel->base);
344	    }
345	    return ret;
346	}
347	
348	static esp_err_t dpi_panel_del(esp_lcd_panel_t *panel)
349	{
350	    esp_lcd_dpi_panel_t *dpi_panel = __containerof(panel, esp_lcd_dpi_panel_t, base);
351	    esp_lcd_dsi_bus_handle_t bus = dpi_panel->bus;
352	    int bus_id = bus->bus_id;
353	    mipi_dsi_hal_context_t *hal = &bus->hal;
354	
355	    // check if the panel is using DMA2D draw bitmap hook
356	    if (dpi_panel->fbcpy_handle) {
357	        ESP_RETURN_ON_FALSE(false, ESP_ERR_INVALID_STATE, TAG, "please call `esp_lcd_dpi_panel_disable_dma2d()` before deleting the panel");
358	    }
359	    // disable the DPI clock
360	    PERIPH_RCC_ATOMIC() {
361	        mipi_dsi_ll_enable_dpi_clock(bus_id, false);
362	    }
363	    // disable the DSI bridge
364	    mipi_dsi_brg_ll_enable(hal->bridge, false);
365	    // free memory
366	    if (dpi_panel->dma_chan) {
367	        dw_gdma_del_channel(dpi_panel->dma_chan);
368	    }
369	    for (int i = 0; i < DPI_PANEL_MAX_FB_NUM; i++) {
370	        if (dpi_panel->fbs[i]) {
371	            free(dpi_panel->fbs[i]);
372	        }
373	    }
374	    for (int i = 0; i < DPI_PANEL_MAX_FB_NUM; i++) {
375	        if (dpi_panel->link_lists[i]) {
376	            dw_gdma_del_link_list(dpi_panel->link_lists[i]);
377	        }
378	    }
379	    if (dpi_panel->brg_intr) {
380	        esp_intr_free(dpi_panel->brg_intr);
381	    }
382	#if CONFIG_PM_ENABLE
383	    if (dpi_panel->pm_lock) {
384	        esp_pm_lock_release(dpi_panel->pm_lock);
385	        esp_pm_lock_delete(dpi_panel->pm_lock);
386	    }
387	#endif
388	    free(dpi_panel);
389	    return ESP_OK;
390	}
