392	esp_err_t esp_lcd_dpi_panel_get_frame_buffer(esp_lcd_panel_handle_t panel, uint32_t fb_num, void **fb0, ...)
393	{
394	    ESP_RETURN_ON_FALSE(panel, ESP_ERR_INVALID_ARG, TAG, "invalid argument");
395	    esp_lcd_dpi_panel_t *dpi_panel = __containerof(panel, esp_lcd_dpi_panel_t, base);
396	    ESP_RETURN_ON_FALSE(fb_num && fb_num <= dpi_panel->num_fbs, ESP_ERR_INVALID_ARG, TAG, "invalid frame buffer number");
397	    void **fb_itor = fb0;
398	    va_list args = {};
399	    va_start(args, fb0);
400	    for (uint32_t i = 0; i < fb_num; i++) {
401	        if (fb_itor) {
402	            *fb_itor = dpi_panel->fbs[i];
403	            if (i < fb_num - 1) {  /* Only get next arg if we're not at the last iteration */
404	                fb_itor = va_arg(args, void **);
405	            }
406	        }
407	    }
408	    va_end(args);
409	    return ESP_OK;
410	}
