23	#define EK79007_DSI_2_LANE      (0x10)
24	#define EK79007_DSI_4_LANE      (0x00)
25	
26	#define EK79007_CMD_SHLR_BIT    (1ULL << 0)
27	#define EK79007_CMD_UPDN_BIT    (1ULL << 1)
28	#define EK79007_MDCTL_VALUE_DEFAULT   (0x01)
