30	typedef struct {
31	    esp_lcd_panel_io_handle_t io;
32	    int reset_gpio_num;
33	    uint8_t madctl_val; // save current value of LCD_CMD_MADCTL register
34	    const ek79007_lcd_init_cmd_t *init_cmds;
35	    uint16_t init_cmds_size;
36	    uint8_t lane_num;
37	    struct {
38	        unsigned int reset_level: 1;
39	    } flags;
40	    // To save the original functions of MIPI DPI panel
41	    esp_err_t (*del)(esp_lcd_panel_t *panel);
42	    esp_err_t (*init)(esp_lcd_panel_t *panel);
43	} ek79007_panel_t;
