47	static esp_err_t panel_ek79007_send_init_cmds(ek79007_panel_t *ek79007);
48	
49	static esp_err_t panel_ek79007_del(esp_lcd_panel_t *panel);
50	static esp_err_t panel_ek79007_init(esp_lcd_panel_t *panel);
51	static esp_err_t panel_ek79007_reset(esp_lcd_panel_t *panel);
52	static esp_err_t panel_ek79007_mirror(esp_lcd_panel_t *panel, bool mirror_x, bool mirror_y);
53	static esp_err_t panel_ek79007_invert_color(esp_lcd_panel_t *panel, bool invert_color_data);
54	
55	esp_err_t esp_lcd_new_panel_ek79007(const esp_lcd_panel_io_handle_t io, const esp_lcd_panel_dev_config_t *panel_dev_config,
56	                                    esp_lcd_panel_handle_t *ret_panel)
57	{
58	    ESP_LOGI(TAG, "version: %d.%d.%d", ESP_LCD_EK79007_VER_MAJOR, ESP_LCD_EK79007_VER_MINOR,
59	             ESP_LCD_EK79007_VER_PATCH);
60	    ESP_RETURN_ON_FALSE(io && panel_dev_config && ret_panel, ESP_ERR_INVALID_ARG, TAG, "invalid arguments");
61	    ek79007_vendor_config_t *vendor_config = (ek79007_vendor_config_t *)panel_dev_config->vendor_config;
62	    ESP_RETURN_ON_FALSE(vendor_config && vendor_config->mipi_config.dpi_config && vendor_config->mipi_config.dsi_bus, ESP_ERR_INVALID_ARG, TAG,
63	                        "invalid vendor config");
64	
65	    esp_err_t ret = ESP_OK;
66	    ek79007_panel_t *ek79007 = (ek79007_panel_t *)calloc(1, sizeof(ek79007_panel_t));
67	    ESP_RETURN_ON_FALSE(ek79007, ESP_ERR_NO_MEM, TAG, "no mem for ek79007 panel");
68	
69	    if (panel_dev_config->reset_gpio_num >= 0) {
70	        gpio_config_t io_conf = {
71	            .mode = GPIO_MODE_OUTPUT,
72	            .pin_bit_mask = 1ULL << panel_dev_config->reset_gpio_num,
73	        };
74	        ESP_GOTO_ON_ERROR(gpio_config(&io_conf), err, TAG, "configure GPIO for RST line failed");
75	    }
76	
77	    ek79007->io = io;
78	    ek79007->init_cmds = vendor_config->init_cmds;
79	    ek79007->init_cmds_size = vendor_config->init_cmds_size;
80	    ek79007->lane_num = vendor_config->mipi_config.lane_num;
81	    ek79007->reset_gpio_num = panel_dev_config->reset_gpio_num;
82	    ek79007->flags.reset_level = panel_dev_config->flags.reset_active_high;
83	    ek79007->madctl_val = EK79007_MDCTL_VALUE_DEFAULT;
84	
85	    // Create MIPI DPI panel
86	    ESP_GOTO_ON_ERROR(esp_lcd_new_panel_dpi(vendor_config->mipi_config.dsi_bus, vendor_config->mipi_config.dpi_config, ret_panel), err, TAG,
87	                      "create MIPI DPI panel failed");
88	    ESP_LOGD(TAG, "new MIPI DPI panel @%p", *ret_panel);
89	
90	    // Save the original functions of MIPI DPI panel
91	    ek79007->del = (*ret_panel)->del;
92	    ek79007->init = (*ret_panel)->init;
93	    // Overwrite the functions of MIPI DPI panel
94	    (*ret_panel)->del = panel_ek79007_del;
95	    (*ret_panel)->init = panel_ek79007_init;
96	    (*ret_panel)->reset = panel_ek79007_reset;
97	    (*ret_panel)->mirror = panel_ek79007_mirror;
98	    (*ret_panel)->invert_color = panel_ek79007_invert_color;
99	    (*ret_panel)->user_data = ek79007;
100	    ESP_LOGD(TAG, "new ek79007 panel @%p", ek79007);
101	
102	    return ESP_OK;
