126	static esp_err_t panel_ek79007_send_init_cmds(ek79007_panel_t *ek79007)
127	{
128	    esp_lcd_panel_io_handle_t io = ek79007->io;
129	    const ek79007_lcd_init_cmd_t *init_cmds = NULL;
130	    uint16_t init_cmds_size = 0;
131	    uint8_t lane_command = EK79007_DSI_2_LANE;
132	    bool is_cmd_overwritten = false;
133	
134	    switch (ek79007->lane_num) {
135	    case 0:
136	    case 2:
137	        lane_command = EK79007_DSI_2_LANE;
138	        break;
139	    case 4:
140	        lane_command = EK79007_DSI_4_LANE;
141	        break;
142	    default:
143	        ESP_LOGE(TAG, "Invalid lane number %d", ek79007->lane_num);
144	        return ESP_ERR_INVALID_ARG;
145	    }
146	    ESP_RETURN_ON_ERROR(esp_lcd_panel_io_tx_param(io, EK79007_PAD_CONTROL, (uint8_t[]) {
147	        lane_command,
148	    }, 1), TAG, "send command failed");
149	
150	    // vendor specific initialization, it can be different between manufacturers
151	    // should consult the LCD supplier for initialization sequence code
152	    if (ek79007->init_cmds) {
153	        init_cmds = ek79007->init_cmds;
154	        init_cmds_size = ek79007->init_cmds_size;
155	    } else {
156	        init_cmds = vendor_specific_init_default;
157	        init_cmds_size = sizeof(vendor_specific_init_default) / sizeof(ek79007_lcd_init_cmd_t);
158	    }
159	
160	    for (int i = 0; i < init_cmds_size; i++) {
161	        // Check if the command has been used or conflicts with the internal
162	        if (init_cmds[i].data_bytes > 0) {
163	            switch (init_cmds[i].cmd) {
164	            case LCD_CMD_MADCTL:
165	                is_cmd_overwritten = true;
166	                ek79007->madctl_val = ((uint8_t *)init_cmds[i].data)[0];
167	                break;
168	            default:
169	                is_cmd_overwritten = false;
170	                break;
171	            }
172	
173	            if (is_cmd_overwritten) {
174	                is_cmd_overwritten = false;
175	                ESP_LOGW(TAG, "The %02Xh command has been used and will be overwritten by external initialization sequence",
176	                         init_cmds[i].cmd);
177	            }
178	        }
179	
180	        // Send command
181	        ESP_RETURN_ON_ERROR(esp_lcd_panel_io_tx_param(io, init_cmds[i].cmd, init_cmds[i].data, init_cmds[i].data_bytes), TAG, "send command failed");
182	        vTaskDelay(pdMS_TO_TICKS(init_cmds[i].delay_ms));
183	    }
184	
185	    ESP_LOGD(TAG, "send init commands success");
186	
187	    return ESP_OK;
188	}
