45	void mipi_dsi_hal_configure_phy_pll(mipi_dsi_hal_context_t *hal, uint32_t phy_clk_src_freq_hz, float lane_bit_rate_mbps)
46	{
47	    // Formula: f_vco = M/N * f_ref
48	    // where the M is Feedback Multiplication Ratio, N is Input Frequency Division Ratio
49	    float ref_freq_mhz = (float)phy_clk_src_freq_hz / 1000.0f / 1000.0f;
50	    float vco_freq_mhz = lane_bit_rate_mbps;
51	    uint8_t pll_N = 1;
52	    uint16_t pll_M = 0;
53	    // 5MHz <= f_ref/N <= 40MHz
54	    uint8_t min_N = MAX(1, (uint8_t)(ref_freq_mhz / 40.0f));
55	    uint8_t max_N = (uint8_t)(ref_freq_mhz / 5.0f);
56	    float min_delta = INFINITY;
57	    for (uint8_t n = min_N; n <= max_N; n++) {
58	        uint16_t m = (uint16_t)(vco_freq_mhz * n / ref_freq_mhz);
59	        // M must be even number
60	        if ((m & 0x01) == 0) {
61	            float delta = fabsf(vco_freq_mhz - ref_freq_mhz * m / n);
62	            if (delta < min_delta) {
63	                min_delta = delta;
64	                pll_M = m;
65	                pll_N = n;
66	                if (min_delta < 0.01f) {
67	                    break;
68	                }
69	            }
70	        }
71	    }
72	    HAL_ASSERT(pll_M && pll_N);
73	
74	    // search for the best PLL range
75	    uint8_t hs_freq_sel = 0;
76	    for (size_t i = 0; i < num_of_soc_mipi_dsi_phy_pll_ranges; i++) {
77	        if (lane_bit_rate_mbps >= soc_mipi_dsi_phy_pll_ranges[i].start_mbps &&
78	                lane_bit_rate_mbps <= soc_mipi_dsi_phy_pll_ranges[i].end_mbps) {
79	            hs_freq_sel = soc_mipi_dsi_phy_pll_ranges[i].hs_freq_range_sel;
80	            break;
81	        }
82	    }
83	
84	    mipi_dsi_hal_phy_write_register(hal, 0x44, hs_freq_sel << 1);
85	    // make use of the N and M factors that configured in the 0x17 and 0x18
86	    mipi_dsi_hal_phy_write_register(hal, 0x19, 0x30);
87	    mipi_dsi_hal_phy_write_register(hal, 0x17, pll_N - 1);
88	    mipi_dsi_hal_phy_write_register(hal, 0x18, ((pll_M - 1) & 0x1F));
89	    mipi_dsi_hal_phy_write_register(hal, 0x18, 0x80 | (((pll_M - 1) >> 5) & 0x0F));
90	    // update the real lane bit rate
91	    hal->lane_bit_rate_mbps = ref_freq_mhz * (float)pll_M / (float)pll_N;
92	    HAL_LOGD(TAG, "phy pll: ref=%" PRIu32 "Hz, lane_bit_rate=%.2f Mbps, M=%" PRId16 ", N=%" PRId8 ", hsfreqrange=%" PRId8,
93	             phy_clk_src_freq_hz, (double)hal->lane_bit_rate_mbps, pll_M, pll_N, hs_freq_sel);
94	}
95	
96	void mipi_dsi_hal_phy_write_register(mipi_dsi_hal_context_t *hal, uint8_t reg_addr, uint8_t reg_val)
97	{
98	    // disable the test clear pin, enable the interface to write values to the PHY internal registers
99	    mipi_dsi_phy_ll_write_clock(hal->host, 0, false);
100	    // load PHY register address
101	    mipi_dsi_phy_ll_write_reg_addr(hal->host, reg_addr);
102	    // the address write operation is set on the falling edge of the test clock
103	    mipi_dsi_phy_ll_write_clock(hal->host, 1, false);
104	    mipi_dsi_phy_ll_write_clock(hal->host, 0, false);
105	    // load PHY register value
106	    mipi_dsi_phy_ll_write_reg_val(hal->host, reg_val);
107	    // the data write operation is set on the rising edge of the test clock
108	    mipi_dsi_phy_ll_write_clock(hal->host, 1, false);
109	    mipi_dsi_phy_ll_write_clock(hal->host, 0, false);
110	}
