112	void mipi_dsi_hal_host_gen_write_dcs_command(mipi_dsi_hal_context_t *hal, uint8_t vc,
113	                                             uint32_t command, uint32_t command_bytes, const void *param, uint16_t param_size)
114	{
115	    mipi_dsi_data_type_t dt = 0;
116	    uint8_t pkt_hdr_msb = 0;
117	    uint8_t pkt_hdr_lsb = 0;
118	    const uint8_t *payload = param;
119	    // the payload size is the command size plus the parameter size
120	    uint32_t payload_size = command_bytes + param_size;
121	
122	    // merge the command and some bytes of parameters into one 32-bit word
123	    uint32_t temp = command & ((1U << (8 * command_bytes)) - 1);
124	    uint16_t merged_size = MIN(4 - command_bytes, param_size);
125	    for (int i = 0; i < merged_size; i++) {
126	        temp |= payload[i] << (8 * (i + command_bytes));
127	    }
128	
129	    if (payload_size > 2) {
130	        // write the first 32-bit word into FIFO
131	        while (mipi_dsi_host_ll_gen_is_write_fifo_full(hal->host));
132	        mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
133	
134	        // write the remaining parameters into FIFO
135	        payload += merged_size;
136	        uint32_t remain_size = param_size - merged_size;
137	        while (remain_size >= 4) {
138	            // use memcpy to avoid unaligned memory access
139	            memcpy(&temp, payload, sizeof(uint32_t));
140	            while (mipi_dsi_host_ll_gen_is_write_fifo_full(hal->host));
141	            mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
142	            payload += 4;
143	            remain_size -= 4;
144	        }
145	        if (remain_size) {
146	            temp = 0;
147	            // use memcpy to avoid unaligned memory access and buffer over-read
148	            memcpy(&temp, payload, remain_size);
149	            while (mipi_dsi_host_ll_gen_is_write_fifo_full(hal->host));
150	            mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
151	        }
152	
153	        dt = MIPI_DSI_DT_DCS_LONG_WRITE;
154	        pkt_hdr_msb = (payload_size >> 8) & 0xFF;
155	        pkt_hdr_lsb = payload_size & 0xFF;
156	    } else if (payload_size == 2) {
157	        dt = MIPI_DSI_DT_DCS_SHORT_WRITE_1;
158	        pkt_hdr_msb = (temp >> 8) & 0xFF;
159	        pkt_hdr_lsb = temp & 0xFF;
160	    } else if (payload_size == 1) {
161	        dt = MIPI_DSI_DT_DCS_SHORT_WRITE_0;
162	        pkt_hdr_msb = (temp >> 8) & 0xFF;
163	        pkt_hdr_lsb = temp & 0xFF;
164	    }
165	
166	    // write the packet header
167	    while (mipi_dsi_host_ll_gen_is_cmd_fifo_full(hal->host));
168	    mipi_dsi_host_ll_gen_set_packet_header(hal->host, vc, dt, pkt_hdr_msb, pkt_hdr_lsb);
169	}
170	
171	void mipi_dsi_hal_host_gen_write_short_packet(mipi_dsi_hal_context_t *hal, uint8_t vc, mipi_dsi_data_type_t dt, uint16_t header_data)
172	{
173	    uint8_t msb = (header_data >> 8) & 0xFF;
174	    uint8_t lsb = header_data & 0xFF;
175	    while (mipi_dsi_host_ll_gen_is_cmd_fifo_full(hal->host));
176	    mipi_dsi_host_ll_gen_set_packet_header(hal->host, vc, dt, msb, lsb);
177	}
178	
179	void mipi_dsi_hal_host_gen_write_long_packet(mipi_dsi_hal_context_t *hal, uint8_t vc, mipi_dsi_data_type_t dt, const void *buffer, uint16_t buffer_size)
180	{
181	    const uint8_t *payload = buffer;
182	    uint32_t remain_size = buffer_size;
183	    uint32_t temp = 0;
184	    while (remain_size >= 4) {
185	        // use memcpy to avoid unaligned memory access
186	        memcpy(&temp, payload, sizeof(uint32_t));
187	        while (mipi_dsi_host_ll_gen_is_write_fifo_full(hal->host));
188	        mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
189	        payload += 4;
190	        remain_size -= 4;
191	    }
192	    if (remain_size) {
193	        temp = 0;
194	        // use memcpy to avoid unaligned memory access and buffer over-read
195	        memcpy(&temp, payload, remain_size);
196	        while (mipi_dsi_host_ll_gen_is_write_fifo_full(hal->host));
197	        mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
198	    }
199	
200	    uint8_t wc_msb = (buffer_size >> 8) & 0xFF;
201	    uint8_t wc_lsb = buffer_size & 0xFF;
202	    while (mipi_dsi_host_ll_gen_is_cmd_fifo_full(hal->host));
203	    mipi_dsi_host_ll_gen_set_packet_header(hal->host, vc, dt, wc_msb, wc_lsb);
204	}
205	
206	void mipi_dsi_hal_host_gen_read_short_packet(mipi_dsi_hal_context_t *hal, uint8_t vc, mipi_dsi_data_type_t dt, uint16_t header_data, void *ret_buffer, uint16_t buffer_size)
207	{
208	    uint8_t *receive_buffer = (uint8_t *)ret_buffer;
209	    // set the maximum returned data size, it should equal to the parameter size of the read command
210	    mipi_dsi_hal_host_gen_write_short_packet(hal, vc, MIPI_DSI_DT_SET_MAXIMUM_RETURN_PKT, buffer_size);
211	    // make sure command mode is on
212	    mipi_dsi_host_ll_enable_video_mode(hal->host, false);
213	    // make sure receiving is enabled
214	    mipi_dsi_host_ll_enable_bta(hal->host, true);
215	    // listen to the same virtual channel as the one sent to
216	    mipi_dsi_host_ll_gen_set_rx_vcid(hal->host, vc);
217	    mipi_dsi_hal_host_gen_write_short_packet(hal, vc, dt, header_data);
218	    while (mipi_dsi_host_ll_gen_is_read_cmd_busy(hal->host));
219	    // wait data to come into the fifo
220	    while (mipi_dsi_host_ll_gen_is_read_fifo_empty(hal->host));

