382	esp_err_t dw_gdma_new_link_list(const dw_gdma_link_list_config_t *config, dw_gdma_link_list_handle_t *ret_list)
383	{
384	    esp_err_t ret = ESP_OK;
385	    ESP_RETURN_ON_FALSE(config && ret_list, ESP_ERR_INVALID_ARG, TAG, "invalid argument");
386	    dw_gdma_link_list_item_t *items = NULL;
387	    dw_gdma_link_list_t *list = NULL;
388	    uint32_t num_items = config->num_items;
389	    list = heap_caps_calloc(1, sizeof(dw_gdma_link_list_t), DW_GDMA_MEM_ALLOC_CAPS);
390	    ESP_GOTO_ON_FALSE(list, ESP_ERR_NO_MEM, err, TAG, "no mem for link list");
391	    // allocate memory for link list items, from internal memory
392	    // the link list items has its own alignment requirement, the heap allocator can help handle the cache alignment as well
393	    items = heap_caps_aligned_calloc(DW_GDMA_LL_LINK_LIST_ALIGNMENT, num_items, sizeof(dw_gdma_link_list_item_t), MALLOC_CAP_INTERNAL | MALLOC_CAP_DMA);
394	    ESP_GOTO_ON_FALSE(items, ESP_ERR_NO_MEM, err, TAG, "no mem for link list items");
395	    // do memory sync when the link list items are cached
396	    uint32_t data_cache_line_size = cache_hal_get_cache_line_size(CACHE_LL_LEVEL_INT_MEM, CACHE_TYPE_DATA);
397	    if (data_cache_line_size) {
398	        // write back and then invalidate the cache, because later we will read/write the link list items by non-cacheable address
399	        ESP_GOTO_ON_ERROR(esp_cache_msync(items, num_items * sizeof(dw_gdma_link_list_item_t),
400	                                          ESP_CACHE_MSYNC_FLAG_DIR_C2M | ESP_CACHE_MSYNC_FLAG_INVALIDATE | ESP_CACHE_MSYNC_FLAG_UNALIGNED),
401	                          err, TAG, "cache sync failed");
402	    }
403	
404	    list->num_items = num_items;
405	    list->items = items;
406	    // want to use non-cached address to operate the link list items
407	    list->items_nc = (dw_gdma_link_list_item_t *)DW_GDMA_GET_NON_CACHE_ADDR(items);
408	
409	    // set up the link list
410	    for (size_t i = 0; i < num_items; i++) {
411	        dw_gdma_ll_lli_set_next_item_addr(list->items_nc + i, (uint32_t)(list->items + i + 1));
412	        // set master port for the link list
413	        dw_gdma_ll_lli_set_link_list_master_port(list->items_nc + i, DW_GDMA_LL_MASTER_PORT_MEMORY);
414	    }
415	    switch (config->link_type) {
416	    case DW_GDMA_LINKED_LIST_TYPE_CIRCULAR:
417	        dw_gdma_ll_lli_set_next_item_addr(list->items_nc + num_items - 1, (uint32_t)(list->items));
418	        break;
419	    case DW_GDMA_LINKED_LIST_TYPE_SINGLY:
420	        dw_gdma_ll_lli_set_next_item_addr(list->items_nc + num_items - 1, 0);
421	        break;
422	    }
423	
424	    ESP_LOGD(TAG, "new link list @%p, items @%p", list, items);
425	    *ret_list = list;
426	    return ESP_OK;
427	err:
428	    if (list) {
429	        free(list);
430	    }
431	    if (items) {
432	        free(items);
433	    }
434	    return ret;
435	}
