492	    dw_gdma_ll_channel_set_dst_addr(hal->dev, chan_id, config->dst.addr);
493	    // transfer size
494	    dw_gdma_ll_channel_set_trans_block_size(hal->dev, chan_id, config->size);
495	    // [Ctrl0] register
