502	    // set burst items
503	    dw_gdma_ll_channel_set_src_burst_items(hal->dev, chan_id, config->src.burst_items);
504	    dw_gdma_ll_channel_set_dst_burst_items(hal->dev, chan_id, config->dst.burst_items);
505	    // set burst mode
506	    dw_gdma_ll_channel_set_src_burst_mode(hal->dev, chan_id, config->src.burst_mode);
507	    dw_gdma_ll_channel_set_dst_burst_mode(hal->dev, chan_id, config->dst.burst_mode);
508	    // [Ctrl1] register
509	    // set burst length
