579	void dw_gdma_channel_default_isr(void *args)
580	{
581	    dw_gdma_channel_t *chan = (dw_gdma_channel_t *)args;
582	    dw_gdma_group_t *group = chan->group;
583	    dw_gdma_hal_context_t *hal = &group->hal;
584	    int chan_id = chan->chan_id;
585	    bool need_yield = false;
586	    // clear pending interrupt event
587	    uint32_t intr_status = dw_gdma_ll_channel_get_intr_status(hal->dev, chan_id);
588	    dw_gdma_ll_channel_clear_intr(hal->dev, chan_id, intr_status);
589	
590	    // call user callbacks
591	    if (intr_status & DW_GDMA_LL_CHANNEL_EVENT_SHADOWREG_OR_LLI_INVALID_ERR) {
592	        if (chan->cbs.on_invalid_block) {
593	            intptr_t invalid_lli_addr = dw_gdma_ll_channel_get_current_link_list_item_addr(hal->dev, chan_id);
594	            dw_gdma_break_event_data_t edata = {
595	                .invalid_lli = (dw_gdma_lli_handle_t)DW_GDMA_GET_NON_CACHE_ADDR(invalid_lli_addr),
596	            };
597	            if (chan->cbs.on_invalid_block(chan, &edata, chan->user_data)) {
598	                need_yield = true;
599	            }
600	        }
601	    }
602	
603	    if (intr_status & DW_GDMA_LL_CHANNEL_EVENT_BLOCK_TFR_DONE) {
604	        if (chan->cbs.on_block_trans_done) {
605	            dw_gdma_trans_done_event_data_t edata = {};
606	            if (chan->cbs.on_block_trans_done(chan, &edata, chan->user_data)) {
607	                need_yield = true;
608	            }
609	        }
610	    }
611	
612	    if (intr_status & DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE) {
613	        if (chan->cbs.on_full_trans_done) {
614	            dw_gdma_trans_done_event_data_t edata = {};
615	            if (chan->cbs.on_full_trans_done(chan, &edata, chan->user_data)) {
616	                need_yield = true;
617	            }
618	        }
619	    }
620	
621	    if (need_yield) {
622	        portYIELD_FROM_ISR();
623	    }
624	}
