626	static esp_err_t dw_gdma_install_channel_interrupt(dw_gdma_channel_t *chan)
627	{
628	    esp_err_t ret = ESP_OK;
629	    dw_gdma_group_t *group = chan->group;
630	    dw_gdma_hal_context_t *hal = &group->hal;
631	    int chan_id = chan->chan_id;
632	    // clear pending events
633	    dw_gdma_ll_channel_enable_intr_propagation(hal->dev, chan_id, UINT32_MAX, false);
634	    dw_gdma_ll_channel_clear_intr(hal->dev, chan_id, UINT32_MAX);
635	
636	    // pre-alloc a interrupt handle, with handler disabled
637	    // DW_GDMA multiple channels share the same interrupt source, so we use a shared interrupt handle
638	    intr_handle_t intr = NULL;
639	    int isr_flags = DW_GDMA_INTR_ALLOC_FLAGS | ESP_INTR_FLAG_SHARED;
640	    if (group->intr_priority) {
641	        isr_flags |= 1 << (group->intr_priority);
642	    } else {
643	        isr_flags |= DW_GDMA_ALLOW_INTR_PRIORITY_MASK;
644	    }
645	    ret = esp_intr_alloc_intrstatus(ETS_DW_GDMA_INTR_SOURCE, isr_flags,
646	                                    (uint32_t)dw_gdma_ll_get_intr_status_reg(hal->dev), DW_GDMA_LL_CHANNEL_EVENT_MASK(chan_id),
647	                                    dw_gdma_channel_default_isr, chan, &intr);
648	    ESP_RETURN_ON_ERROR(ret, TAG, "alloc interrupt failed");
649	
650	    ESP_LOGD(TAG, "install interrupt service for channel (%d,%d)", group->group_id, chan_id);
651	    chan->intr = intr;
652	    return ESP_OK;
653	}
