655	esp_err_t dw_gdma_channel_register_event_callbacks(dw_gdma_channel_handle_t chan, dw_gdma_event_callbacks_t *cbs, void *user_data)
656	{
657	    ESP_RETURN_ON_FALSE(chan && cbs, ESP_ERR_INVALID_ARG, TAG, "invalid argument");
658	    dw_gdma_group_t *group = chan->group;
659	    dw_gdma_hal_context_t *hal = &group->hal;
660	    int chan_id = chan->chan_id;
661	
662	#if CONFIG_DW_GDMA_ISR_IRAM_SAFE
663	    if (cbs->on_block_trans_done) {
664	        ESP_RETURN_ON_FALSE(esp_ptr_in_iram(cbs->on_block_trans_done), ESP_ERR_INVALID_ARG,
665	                            TAG, "on_block_trans_done not in IRAM");
666	    }
667	    if (cbs->on_full_trans_done) {
668	        ESP_RETURN_ON_FALSE(esp_ptr_in_iram(cbs->on_full_trans_done), ESP_ERR_INVALID_ARG,
669	                            TAG, "on_full_trans_done not in IRAM");
670	    }
671	    if (cbs->on_invalid_block) {
672	        ESP_RETURN_ON_FALSE(esp_ptr_in_iram(cbs->on_invalid_block), ESP_ERR_INVALID_ARG,
673	                            TAG, "on_invalid_block not in IRAM");
674	    }
675	    if (user_data) {
676	        ESP_RETURN_ON_FALSE(esp_ptr_internal(user_data), ESP_ERR_INVALID_ARG,
677	                            TAG, "user context not in internal RAM");
678	    }
679	#endif // CONFIG_DW_GDMA_ISR_IRAM_SAFE
680	
681	    // lazy install interrupt service
682	    if (!chan->intr) {
683	        ESP_RETURN_ON_ERROR(dw_gdma_install_channel_interrupt(chan), TAG, "install interrupt service failed");
684	    }
685	
686	    // enable the event to be able to trigger an interrupt
687	    dw_gdma_ll_channel_enable_intr_propagation(hal->dev, chan_id, DW_GDMA_LL_CHANNEL_EVENT_BLOCK_TFR_DONE, cbs->on_block_trans_done != NULL);
688	    dw_gdma_ll_channel_enable_intr_propagation(hal->dev, chan_id, DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE, cbs->on_full_trans_done != NULL);
689	    dw_gdma_ll_channel_enable_intr_propagation(hal->dev, chan_id, DW_GDMA_LL_CHANNEL_EVENT_SHADOWREG_OR_LLI_INVALID_ERR, cbs->on_invalid_block != NULL);
690	
691	    chan->user_data = user_data;
692	    memcpy(&chan->cbs, cbs, sizeof(dw_gdma_event_callbacks_t));
693	
694	    return ESP_OK;
695	}
